          .allMatches(secretsBlock)
          .map((m) => m.group(1)!)
          .toSet();
      expect(mapped, declared,
          reason: '$stub maps {${mapped.join(', ')}} but the factory '
              'declares {${declared.join(', ')}} — mapping undeclared '
              'secrets (or missing declared ones) is a startup failure');
    }
  });
