Set<String> _declaredSecrets(String factoryPath) {
  final yml = File('agents/$factoryPath').readAsStringSync();
  final block = yml.split('    secrets:').last.split('\n\n').first;
  return RegExp(r'^\s{6}([A-Z_]+):', multiLine: true)
      .allMatches(block)
      .map((m) => m.group(1)!)
      .toSet();
